def minimum_spanning_tree(weight_by_edge):
    group_by_node = {}
    mst_edges = set()

    for edge in sorted(weight_by_edge, key=weight_by_edge.__getitem__):
        u, v = edge
        if group_by_node.setdefault(u, {u}) != group_by_node.setdefault(v, {v}):
            mst_edges.add(edge)
            group_by_node[u].update(group_by_node[v])
            for node in list(group_by_node[v]):
                group_by_node[node].update(group_by_node[u])

    return mst_edges




"""
Minimum Spanning Tree


Kruskal's algorithm implementation.

Input:
    weight_by_edge: A dict of the form {(u, v): weight} for every undirected graph edge {u, v}

Precondition:
    The input graph is connected

Output:
    A set of edges that connects all the vertices of the input graph and has the least possible total weight.

Example:
    >>> minimum_spanning_tree({
    ...     (1, 2): 10,
    ...     (2, 3): 15,
    ...     (3, 4): 10,
    ...     (1, 4): 10
    ... })
    {(1, 2), (3, 4), (1, 4)}
"""", "explanation": "The loop `for node in group_by_node[v]` iterates over a set that may be modified during iteration. When `u` is already in `group_by_node[v]` (i.e., they share the same set object), line 10's `group_by_node[u].update(group_by_node[v])` mutates the set being iterated, causing "Set changed size during iteration". Fixed by iterating over `list(group_by_node[v])` — a snapshot copy of the set."}

